<script setup>import {ref} from 'vue';import PageHero from '../components/PageHero.vue';import {company} from '../data/company';const sent=ref(false);</script><template><PageHero eyebrow="CONTACT IMAGECOPY" title="聯絡我們" description="有印刷需求或檔案問題，歡迎與我們聯繫。"/><section class="container contact-layout"><div class="contact-info"><p class="eyebrow">CONTACT INFORMATION</p><h2>讓我們一起確認<br>最適合的製作方式。</h2><p>正式地址與營業資訊將於取得最新資料後更新。</p><dl><dt>地址</dt><dd>{{company.address}}</dd><dt>電話</dt><dd>{{company.phone}}</dd><dt>Email</dt><dd>{{company.email}}</dd><dt>營業時間</dt><dd>{{company.hours}}</dd></dl><div class="map-placeholder">MAP AREA<br><small>地圖區域</small></div></div><form @submit.prevent="sent=true"><h2>聯絡表單</h2><p v-if="sent" class="success">已收到你的訊息（目前為前端展示）。</p><label>姓名<input required placeholder="請輸入姓名"></label><label>電話<input placeholder="請輸入電話"></label><label>Email<input type="email" placeholder="請輸入 Email"></label><label>內容<textarea rows="5" placeholder="請描述你的需求"></textarea></label><button class="btn" type="submit">送出表單 <span>→</span></button></form></section></template>
